-- Isolated content-catalogue fixture, captured 2026-10-06. UUIDs pseudonymized.
-- Actual column/default/check/unique definitions and internal FKs; external FKs
-- and self-ancestry FKs and production triggers excluded. This is not live Auth or full-schema acceptance.
create type public.user_role as enum ('student','teacher','parent','admin','content_admin','school_admin');
create type public.content_status as enum ('draft','review','published','archived');
