alter table public.item_templates add constraint item_templates_prospective_evidence_blueprint_check CHECK (((created_at < '2026-10-02 07:00:00+00'::timestamp with time zone) OR ((generation_config @> '{"authoringProfileVersion": "haiedu-evidence-blueprint-v1", "evidenceBlueprintPolicy": "distinct-purpose-v1"}'::jsonb) AND (jsonb_typeof(COALESCE((generation_config -> 'requiredEvidencePurposes'::text), 'null'::jsonb)) = 'array'::text) AND
CASE
    WHEN (jsonb_typeof(COALESCE((generation_config -> 'requiredEvidencePurposes'::text), 'null'::jsonb)) = 'array'::text) THEN ((jsonb_array_length((generation_config -> 'requiredEvidencePurposes'::text)) >= 1) AND (jsonb_array_length((generation_config -> 'requiredEvidencePurposes'::text)) <= 4))
    ELSE false
END AND COALESCE(((generation_config -> 'requiredEvidencePurposes'::text) <@ '["core_understanding", "application", "misconception_diagnosis", "transfer_reasoning"]'::jsonb), false))));
