insert into public.item_options select * from jsonb_populate_recordset(null::public.item_options,'[{"id": "16bc95c4-5e08-5453-a58e-97617820f8c5", "item_id": "9420cf3b-1b07-55f2-85af-2797b9f830a7", "content_en": null, "content_hy": "Տաքացնելիս պղինձը կորցնում է զանգվածը։", "option_key": "C", "display_order": 3}, {"id": "743378df-2e25-5a50-8179-8574c41699db", "item_id": "9420cf3b-1b07-55f2-85af-2797b9f830a7", "content_en": null, "content_hy": "Տաքացնելիս պղնձի յուրաքանչյուր մասնիկ անընդհատ մեծանում է։", "option_key": "A", "display_order": 1}, {"id": "aee8d649-c4de-5a81-b460-0801151372aa", "item_id": "9420cf3b-1b07-55f2-85af-2797b9f830a7", "content_en": null, "content_hy": "Տաքացնելիս նոր պղնձի մասնիկներ են առաջանում։", "option_key": "B", "display_order": 2}, {"id": "69103923-175b-5fb2-8ea8-d12cf2db7ab2", "item_id": "7b1c0e42-a43f-5138-a739-c697f1df001e", "content_en": null, "content_hy": "Մի նյութի մասնիկները տեղավորվում են մյուս նյութի մասնիկների միջև եղած ազատ տարածություններում։", "option_key": "C", "display_order": 3}, {"id": "637d95b3-ad99-5dc0-893d-14c9b0fa4052", "item_id": "c35ffa5b-fb48-5879-98ac-84bedc485e9d", "content_en": null, "content_hy": "Նույնիսկ պինդ նյութի մասնիկների միջև կան ազատ տարածություններ։", "option_key": "A", "display_order": 1}, {"id": "03dfd243-8560-51cf-a2ed-1d63242d7072", "item_id": "7b1c0e42-a43f-5138-a739-c697f1df001e", "content_en": null, "content_hy": "Ջուրն ու սպիրտը հոծ են և մասնիկներ չունեն։", "option_key": "D", "display_order": 4}, {"id": "290a47bc-5de4-5905-932f-0fac05bff74d", "item_id": "c35ffa5b-fb48-5879-98ac-84bedc485e9d", "content_en": null, "content_hy": "Երկաթը բարձր ջերմաստիճանում դադարում է նյութ լինելուց։", "option_key": "B", "display_order": 2}, {"id": "b356506c-40a6-568e-9ed3-90c0596bf372", "item_id": "c35ffa5b-fb48-5879-98ac-84bedc485e9d", "content_en": null, "content_hy": "Պինդ մարմինները կազմված չեն մասնիկներից։", "option_key": "D", "display_order": 4}, {"id": "f5cae94a-ab89-542f-a565-7912f0ce7972", "item_id": "7b1c0e42-a43f-5138-a739-c697f1df001e", "content_en": null, "content_hy": "Խառնելիս հեղուկների զանգվածը անհետանում է։", "option_key": "B", "display_order": 2}, {"id": "eee85f20-9e6b-5302-ab66-82af6a6089b1", "item_id": "9600a851-40ec-534a-9272-076ce6705b69", "content_en": null, "content_hy": "Լուծվելիս ջրի զանգվածը փոքրանում է։", "option_key": "C", "display_order": 3}, {"id": "9a508fe0-9bfc-565a-bd66-5a19c03b2d83", "item_id": "9420cf3b-1b07-55f2-85af-2797b9f830a7", "content_en": null, "content_hy": "Տաքացնելիս մասնիկների միջև միջին հեռավորությունը մեծանում է։", "option_key": "D", "display_order": 4}, {"id": "98304ad8-c4d3-5a3a-bac7-cbe541b9de78", "item_id": "7b1c0e42-a43f-5138-a739-c697f1df001e", "content_en": null, "content_hy": "Մասնիկների մի մասը ոչնչանում է։", "option_key": "A", "display_order": 1}, {"id": "8b35125c-388c-5438-907e-30f2552ef633", "item_id": "9600a851-40ec-534a-9272-076ce6705b69", "content_en": null, "content_hy": "Ջրի մասնիկների միջև կան ազատ տարածություններ, որոնցում տեղավորվում են աղի մասնիկները։", "option_key": "B", "display_order": 2}, {"id": "0ba19dc8-2d41-5c78-aec4-415e3ed89600", "item_id": "9600a851-40ec-534a-9272-076ce6705b69", "content_en": null, "content_hy": "Աղի մասնիկները վերածվում են ջրի մասնիկների։", "option_key": "D", "display_order": 4}, {"id": "207bdda9-eab7-59bc-a97e-7055fdb3015c", "item_id": "c35ffa5b-fb48-5879-98ac-84bedc485e9d", "content_en": null, "content_hy": "Գազը վերածվում է երկաթի։", "option_key": "C", "display_order": 3}, {"id": "9634b2bb-92ca-5aa1-8f87-20daadbe251f", "item_id": "9600a851-40ec-534a-9272-076ce6705b69", "content_en": null, "content_hy": "Աղը լուծվելիս ամբողջությամբ անհետանում է և այլևս նյութ չէ։", "option_key": "A", "display_order": 1}]'::jsonb);
