insert into public.curriculum_reconciliation_runs select * from jsonb_populate_recordset(null::public.curriculum_reconciliation_runs,'[{"id": "109bf4fc-0aaa-5b59-a821-8170707dca7a", "notes": "Գլուխ II-ի թեկնածու համադրումն է։ Պաշտոնական վերջնարդյունքների բառացիությունը ստուգված է, իսկ հմտությունների կառուցվածքը, չափորոշչային կետային համադրումը և գնահատման ծավալը դեռ պահանջում են բովանդակային ու ֆիզիկայի մասնագետի հաստատում։", "status": "draft", "unit_id": "84562c4e-d523-5245-a410-09798009de5e", "created_at": "2026-09-30T21:40:31.093879+00:00", "reviewed_by": null, "completed_at": null, "source_snapshot": {"retrieved_on": "2026-09-30", "framework_url": "https://www.arlis.am/hy/acts/225446", "programme_url": "https://www.arlis.am/hy/acts/229331", "textbook_role": "supporting_reference", "textbook_title": "Ֆիզիկա 7", "textbook_sha256": "d8404d572f145d4afe924d0b8af900b3d9ed085a37893594667ab07a2ec12904", "textbook_chapter": "Գլուխ II — Նյութի կառուցվածքը", "subject_standard_url": "https://www.arlis.am/hy/acts/229259", "textbook_edition_year": 2023, "textbook_printed_pages": "23–41", "programme_attachment_url": "https://www.arlis.am/acts/files/361998/966f79b4570fa3c6cee0263bd3776ac4aff0fcea6242d2c48121256309f53478", "programme_attachment_sha256": "966f79b4570fa3c6cee0263bd3776ac4aff0fcea6242d2c48121256309f53478"}, "reconciliation_key": "physics7_u02_2026_08_14", "subject_program_id": "cedba47a-b853-54de-8464-60e4a7eede33", "framework_document_id": "352aa551-ca80-5065-80d2-223454479d0b", "programme_document_id": "4a197efb-a548-50c4-a168-0206601d4e67", "subject_standard_document_id": "9db17816-9385-5780-94bd-0cf5ef09ff4f"}]'::jsonb);
insert into public.curriculum_release_item_families select * from jsonb_populate_recordset(null::public.curriculum_release_item_families,'[{"skill_id": "d3749374-f33f-59c7-9113-60816ead63fc", "item_family_id": "fb26eb5f-79e0-56be-aea0-3b69dda47924", "name_hy_snapshot": "Փորձարարական դիտումից նյութի մասնիկային կառուցվածքի եզրակացություն", "rationale_snapshot": "Ընտանիքը գնահատում է փորձարարական դիտումներից նյութի մասնիկային կառուցվածքի վերաբերյալ հիմնավորված եզրակացություն անելը։", "description_snapshot": "Տրված փորձարարական դիտումից ընտրել այն բացատրությունը, որը նյութի վարքը կապում է մասնիկների և նրանց միջև եղած ազատ տարածությունների հետ։", "disposition_snapshot": "new_family", "family_code_snapshot": "PHY7-U02-S02-F01-PARTICULATE-EVIDENCE", "curriculum_release_id": "103a6480-4b64-5dd3-8f4d-f16f70ac3f4a", "mapping_type_snapshot": "direct", "primary_learning_outcome_id": "fd6859bb-e968-55d5-895f-f8b1f1c3930e"}]'::jsonb);
insert into public.item_template_remediation_guides select * from jsonb_populate_recordset(null::public.item_template_remediation_guides,'[{"id": "6676014c-8acd-5b0a-ae52-62b516b053dc", "status": "published", "metadata": {"sprint": "15B.2", "learnerVisible": false, "referenceMetadata": {"notes": "", "sourceUrl": "", "sourceTitle": "", "sourceLocator": ""}}, "title_hy": "Ինչպե՞ս եզրակացություն անել փորձարարական դիտումից", "hint_1_hy": "Ինքդ քեզ հարցրո՛ւ՝ փորձը ցույց է տալիս նյութի անհետացում, թե՞ պարզապես այդ նյութի մասնիկների վերադասավորում։", "hint_2_hy": "Եթե երկու նյութերի խառնուրդի ընդհանուր ծավալը սպասվածից փոքր է, կամ լուծված նյութը տեղավորվում է հեղուկում, ապա մտածի՛ր մասնիկների միջև եղած ազատ տարածությունների մասին։", "created_at": "2026-09-30T22:07:43.605908+00:00", "updated_at": "2026-10-05T13:11:03.203459+00:00", "strategy_hy": "Նախ առանձնացրո՛ւ, թե փորձի ընթացքում ինչը պահպանվեց և ինչը փոխվեց։ Այնուհետև ընտրիր այն բացատրությունը, որը չի ենթադրում նյութի կամ զանգվածի անհետացում և դիտվող երևույթը կապում է մասնիկների ու դրանց միջև եղած տարածությունների հետ։", "guide_version": 3, "item_template_id": "a3c8c472-b017-5249-8a89-ebd87d5abe24", "worked_example_hy": "Օրինակ՝ ջուրն ու սպիրտը խառնելիս դրանց ընդհանուր ծավալը կարող է փոքր լինել առանձին վերցրած ծավալների գումարից, քանի որ մի նյութի մասնիկները տեղավորվում են մյուսի մասնիկների միջև եղած ազատ տարածություններում։", "trigger_error_code": null, "allowed_parameter_keys": []}]'::jsonb);
insert into public.remediation_guide_authoring_versions select * from jsonb_populate_recordset(null::public.remediation_guide_authoring_versions,'[{"id": "64ac9eda-1bbe-5dee-a9af-737b742da2ef", "actor_id": null, "actor_aal": "system", "actor_role": "system", "created_at": "2026-09-30T22:07:43.605908+00:00", "guide_scope": "template", "guide_source_id": "6676014c-8acd-5b0a-ae52-62b516b053dc", "change_rationale": "15B.2 առաջին սևագրի ստեղծում", "content_snapshot": {"hint1Hy": "Հարցրու՝ փորձը ցույց տալի՞ս է, որ նյութն անհետացել է, թե՞ մասնիկները պարզապես այլ կերպ են դասավորվել։", "hint2Hy": "Եթե երկու նյութի ընդհանուր ծավալը սպասվածից փոքր է կամ լուծված նյութը տեղավորվում է հեղուկում, մտածիր մասնիկների միջև եղած ազատ տարածությունների մասին։", "skillId": "d3749374-f33f-59c7-9113-60816ead63fc", "titleHy": "Ինչպե՞ս եզրակացություն անել փորձարարական դիտումից", "metadata": {"sprint": "15B.2", "learnerVisible": false, "referenceMetadata": {"textbookSha256": "d8404d572f145d4afe924d0b8af900b3d9ed085a37893594667ab07a2ec12904", "textbookLocator": "Ֆիզիկա 7 (2023), Գլուխ II, §7, տպագիր էջեր 23-26", "programmeOutcomeLocator": "7-րդ դասարան / Թեմա 2 / Վերջնարդյունքներ / Պարտադիր 1(1)"}}, "strategyHy": "Նախ առանձնացրու, թե փորձի ընթացքում ինչը պահպանվեց և ինչը փոխվեց։ Այնուհետև ընտրիր այն բացատրությունը, որը չի ենթադրում նյութի կամ զանգվածի անհետացում և դիտումը կապում է մասնիկների ու նրանց միջև եղած տարածությունների հետ։", "itemTemplateId": "a3c8c472-b017-5249-8a89-ebd87d5abe24", "workedExampleHy": "Օրինակ՝ ջուրն ու սպիրտը խառնելիս ընդհանուր ծավալը կարող է 2 լիտրից փոքր լինել, որովհետև մի նյութի մասնիկները տեղավորվում են մյուսի մասնիկների միջև եղած ազատ տարածություններում։", "triggerErrorCode": null, "misconceptionCode": "", "allowedParameterKeys": []}, "lifecycle_status": "draft", "authoring_version": 1, "parent_version_id": null, "reference_metadata": {"textbookSha256": "d8404d572f145d4afe924d0b8af900b3d9ed085a37893594667ab07a2ec12904", "textbookLocator": "Ֆիզիկա 7 (2023), Գլուխ II, §7, տպագիր էջեր 23-26", "programmeOutcomeLocator": "7-րդ դասարան / Թեմա 2 / Վերջնարդյունքներ / Պարտադիր 1(1)"}, "published_runtime_version": null}, {"id": "ef31b2e5-2d63-5b24-a28c-44668a1c8d65", "actor_id": "d435fd35-1e9f-5f8b-81dd-7f540f24fbca", "actor_aal": "aal2", "actor_role": "content_admin", "created_at": "2026-10-01T11:39:03.676059+00:00", "guide_scope": "template", "guide_source_id": "6676014c-8acd-5b0a-ae52-62b516b053dc", "change_rationale": "N/A", "content_snapshot": {"hint1Hy": "Հարցրու՝ փորձը ցույց տալի՞ս է, որ նյութն անհետացել է, թե՞ մասնիկները պարզապես այլ կերպ են դասավորվել։", "hint2Hy": "Եթե երկու նյութի ընդհանուր ծավալը սպասվածից փոքր է կամ լուծված նյութը տեղավորվում է հեղուկում, մտածիր մասնիկների միջև եղած ազատ տարածությունների մասին։", "skillId": "d3749374-f33f-59c7-9113-60816ead63fc", "titleHy": "Ինչպե՞ս եզրակացություն անել փորձարարական դիտումից", "metadata": {"sprint": "15B.2", "learnerVisible": false, "referenceMetadata": {"textbookSha256": "d8404d572f145d4afe924d0b8af900b3d9ed085a37893594667ab07a2ec12904", "textbookLocator": "Ֆիզիկա 7 (2023), Գլուխ II, §7, տպագիր էջեր 23-26", "programmeOutcomeLocator": "7-րդ դասարան / Թեմա 2 / Վերջնարդյունքներ / Պարտադիր 1(1)"}}, "strategyHy": "Նախ առանձնացրու, թե փորձի ընթացքում ինչը պահպանվեց և ինչը փոխվեց։ Այնուհետև ընտրիր այն բացատրությունը, որը չի ենթադրում նյութի կամ զանգվածի անհետացում և դիտումը կապում է մասնիկների ու նրանց միջև եղած տարածությունների հետ։", "itemTemplateId": "a3c8c472-b017-5249-8a89-ebd87d5abe24", "workedExampleHy": "Օրինակ՝ ջուրն ու սպիրտը խառնելիս ընդհանուր ծավալը կարող է 2 լիտրից փոքր լինել, որովհետև մի նյութի մասնիկները տեղավորվում են մյուսի մասնիկների միջև եղած ազատ տարածություններում։", "triggerErrorCode": null, "misconceptionCode": "", "allowedParameterKeys": []}, "lifecycle_status": "draft", "authoring_version": 4, "parent_version_id": "d4a2521f-31ac-5672-844d-5c5b1f2de809", "reference_metadata": {"notes": "", "sourceUrl": "", "sourceTitle": "", "sourceLocator": ""}, "publishe