16b053dc", "change_rationale": "լեզվական և շարահյուսական խմբագրումներ", "content_snapshot": {"hint1Hy": "Ինքդ քեզ հարցրո՛ւ՝ փորձը ցույց է տալիս նյութի անհետացում, թե՞ պարզապես այդ նյութի մասնիկների վերադասավորում։", "hint2Hy": "Եթե երկու նյութերի խառնուրդի ընդհանուր ծավալը սպասվածից փոքր է, կամ լուծված նյութը տեղավորվում է հեղուկում, ապա մտածի՛ր մասնիկների միջև եղած ազատ տարածությունների մասին։", "skillId": "d3749374-f33f-59c7-9113-60816ead63fc", "titleHy": "Ինչպե՞ս եզրակացություն անել փորձարարական դիտումից", "metadata": {"sprint": "15B.2", "learnerVisible": false, "referenceMetadata": {"textbookSha256": "d8404d572f145d4afe924d0b8af900b3d9ed085a37893594667ab07a2ec12904", "textbookLocator": "Ֆիզիկա 7 (2023), Գլուխ II, §7, տպագիր էջեր 23-26", "programmeOutcomeLocator": "7-րդ դասարան / Թեմա 2 / Վերջնարդյունքներ / Պարտադիր 1(1)"}}, "strategyHy": "Նախ առանձնացրո՛ւ, թե փորձի ընթացքում ինչը պահպանվեց և ինչը փոխվեց։ Այնուհետև ընտրիր այն բացատրությունը, որը չի ենթադրում նյութի կամ զանգվածի անհետացում և դիտվող երևույթը կապում է մասնիկների ու դրանց միջև եղած տարածությունների հետ։", "itemTemplateId": "a3c8c472-b017-5249-8a89-ebd87d5abe24", "workedExampleHy": "Օրինակ՝ ջուրն ու սպիրտը խառնելիս դրանց ընդհանուր ծավալը կարող է փոքր լինել առանձին վերցրած ծավալների գումարից, քանի որ մի նյութի մասնիկները տեղավորվում են մյուսի մասնիկների միջև եղած ազատ տարածություններում։", "triggerErrorCode": null, "misconceptionCode": "", "allowedParameterKeys": []}, "lifecycle_status": "draft", "authoring_version": 7, "parent_version_id": "154f131c-ac69-51de-a0b1-78a702f85530", "reference_metadata": {"notes": "", "sourceUrl": "", "sourceTitle": "", "sourceLocator": ""}, "published_runtime_version": null}, {"id": "a495c266-ccb9-53ac-a094-fd36014ea303", "actor_id": "d435fd35-1e9f-5f8b-81dd-7f540f24fbca", "actor_aal": "aal2", "actor_role": "content_admin", "created_at": "2026-10-05T13:11:03.203459+00:00", "guide_scope": "template", "guide_source_id": "6676014c-8acd-5b0a-ae52-62b516b053dc", "change_ratio